<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('student');
$quizId = filter_var($_GET['id'] ?? $_POST['quiz_id'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
if (!$quizId) { set_flash('danger', 'Invalid quiz selected.'); redirect('student/courses.php'); }
$quizStatement = db()->prepare("SELECT q.id, q.lesson_id, q.title, q.description, q.pass_percentage, l.title AS lesson_title, l.course_id, c.title AS course_title FROM quizzes q INNER JOIN lessons l ON l.id = q.lesson_id INNER JOIN courses c ON c.id = l.course_id INNER JOIN enrollments e ON e.course_id = l.course_id AND e.user_id = :user_id WHERE q.id = :quiz_id AND q.status = 'published' AND l.status = 'published' AND c.status = 'published'");
$quizStatement->execute(['user_id' => current_user()['id'], 'quiz_id' => $quizId]); $quiz = $quizStatement->fetch();
if (!$quiz) { set_flash('danger', 'Enroll in the course to access this quiz.'); redirect('student/courses.php'); }
$questionStatement = db()->prepare('SELECT id, question_text, points, sort_order FROM questions WHERE quiz_id = :quiz_id ORDER BY sort_order, id'); $questionStatement->execute(['quiz_id' => $quizId]); $questions = $questionStatement->fetchAll();
foreach ($questions as &$question) { $options = db()->prepare('SELECT id, option_text FROM question_options WHERE question_id = :question_id ORDER BY id'); $options->execute(['question_id' => $question['id']]); $question['options'] = $options->fetchAll(); } unset($question);
$errors = [];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!verify_csrf($_POST['csrf_token'] ?? null)) $errors[] = 'Your session token expired. Please try again.';
    if (!$questions) $errors[] = 'This quiz has no questions yet.';
    $submitted = is_array($_POST['answers'] ?? null) ? $_POST['answers'] : [];
    $validOptions = [];
    foreach ($questions as $question) foreach ($question['options'] as $option) $validOptions[(int)$question['id']][(int)$option['id']] = true;
    if (!$errors) {
        $total = 0; $score = 0; $answerRows = [];
        foreach ($questions as $question) { $questionId = (int)$question['id']; $total += (int)$question['points']; $optionId = filter_var($submitted[$questionId] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); if ($optionId && !isset($validOptions[$questionId][$optionId])) $optionId = null; $correctStatement = db()->prepare('SELECT id FROM question_options WHERE id = :option_id AND question_id = :question_id AND is_correct = 1'); $correctStatement->execute(['option_id' => $optionId ?: 0, 'question_id' => $questionId]); $isCorrect = (bool)$correctStatement->fetch(); $points = $isCorrect ? (int)$question['points'] : 0; $score += $points; $answerRows[] = ['question_id' => $questionId, 'option_id' => $optionId ?: null, 'is_correct' => $isCorrect ? 1 : 0, 'points_awarded' => $points]; }
        $percentage = $total > 0 ? round(($score / $total) * 100, 2) : 0; $passed = $percentage >= (float)$quiz['pass_percentage'] ? 1 : 0;
        db()->beginTransaction();
        try { $attempt = db()->prepare('INSERT INTO quiz_attempts (user_id, quiz_id, score, percentage, passed, completed_at) VALUES (:user_id, :quiz_id, :score, :percentage, :passed, CURRENT_TIMESTAMP)'); $attempt->execute(['user_id' => current_user()['id'], 'quiz_id' => $quizId, 'score' => $score, 'percentage' => $percentage, 'passed' => $passed]); $attemptId = (int)db()->lastInsertId(); $answer = db()->prepare('INSERT INTO quiz_answers (attempt_id, question_id, option_id, is_correct, points_awarded) VALUES (:attempt_id, :question_id, :option_id, :is_correct, :points_awarded)'); foreach ($answerRows as $row) $answer->execute(['attempt_id' => $attemptId, 'question_id' => $row['question_id'], 'option_id' => $row['option_id'], 'is_correct' => $row['is_correct'], 'points_awarded' => $row['points_awarded']]); db()->commit();
            record_daily_activity((int)current_user()['id']); award_xp((int)current_user()['id'], 15, 'quiz_complete', $attemptId); if ($passed) award_xp((int)current_user()['id'], 25, 'quiz_pass', $attemptId); sync_achievements_and_badges((int)current_user()['id']); if ($passed) { set_flash('success', 'Congratulations! You passed the quiz with ' . $percentage . '%.'); notify_user((int)current_user()['id'], 'Congratulations! Quiz passed', 'You passed ' . $quiz['title'] . ' with ' . $percentage . '%.'); } else { set_flash('info', 'Quiz submitted. Your score is ' . $percentage . '%.'); notify_user((int)current_user()['id'], 'Quiz completed', 'You scored ' . $percentage . '% on ' . $quiz['title'] . '.'); } redirect('student/quiz.php?id=' . $quizId . '&attempt=' . $attemptId);
        } catch (Throwable $exception) { if (db()->inTransaction()) db()->rollBack(); $errors[] = 'The quiz could not be submitted. Please try again.'; }
    }
}
$attempt = null; $answerResults = [];
if (isset($_GET['attempt'])) { $attemptId = filter_var($_GET['attempt'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); if ($attemptId) { $attemptStatement = db()->prepare('SELECT id, score, percentage, passed, completed_at FROM quiz_attempts WHERE id = :id AND user_id = :user_id AND quiz_id = :quiz_id'); $attemptStatement->execute(['id' => $attemptId, 'user_id' => current_user()['id'], 'quiz_id' => $quizId]); $attempt = $attemptStatement->fetch(); if ($attempt) { $answerStatement = db()->prepare('SELECT qa.question_id, qa.is_correct, qa.points_awarded, qo.option_text AS selected_text, correct.option_text AS correct_text FROM quiz_answers qa LEFT JOIN question_options qo ON qo.id = qa.option_id LEFT JOIN question_options correct ON correct.question_id = qa.question_id AND correct.is_correct = 1 WHERE qa.attempt_id = :attempt_id'); $answerStatement->execute(['attempt_id' => $attemptId]); foreach ($answerStatement->fetchAll() as $answer) $answerResults[(int)$answer['question_id']] = $answer; } } }
$celebrate = $attempt && (bool)$attempt['passed'];
$pageTitle = $attempt ? 'Quiz result' : $quiz['title']; require __DIR__ . '/../includes/header.php';
?>
<div class="py-4"><a class="text-decoration-none" href="<?= e(app_url('student/course.php?id=' . $quiz['course_id'])) ?>">&larr; <?= e($quiz['course_title']) ?></a><div class="mt-3 mb-4"><h1 class="h2 fw-bold"><?= e($quiz['title']) ?></h1><p class="text-secondary mb-0"><?= e($quiz['description'] ?? '') ?></p></div><?php if ($errors): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?><?php if ($attempt): ?><div class="card mb-4"><div class="card-body text-center p-5"><h2 class="<?= $attempt['passed'] ? 'text-success' : 'text-danger' ?>"><?= $attempt['passed'] ? 'Passed' : 'Keep practicing' ?></h2><div class="display-4 fw-bold"><?= e((string)$attempt['percentage']) ?>%</div><p class="text-secondary">Score: <?= e((string)$attempt['score']) ?> points. Passing score: <?= e((string)$quiz['pass_percentage']) ?>%.</p><a class="btn btn-primary" href="<?= e(app_url('student/quiz.php?id=' . $quizId)) ?>">Try again</a></div></div><div class="card"><div class="card-body"><h2 class="h5">Answer review</h2><?php foreach ($questions as $index => $question): $answer = $answerResults[(int)$question['id'] ?? null] ?? null; ?><div class="border-bottom py-3"><strong><?= $index + 1 ?>. <?= e($question['question_text']) ?></strong><div class="small <?= ($answer && $answer['is_correct']) ? 'text-success' : 'text-danger' ?>"><?= $answer && $answer['is_correct'] ? 'Correct' : 'Incorrect' ?><?php if ($answer && $answer['selected_text']): ?>: <?= e($answer['selected_text']) ?><?php endif; ?><?php if ($answer && !$answer['is_correct']): ?> | Correct answer: <?= e((string)$answer['correct_text']) ?><?php endif; ?></div></div><?php endforeach; ?></div></div><?php else: ?><form method="post" data-disable-submit><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="quiz_id" value="<?= (int)$quizId ?>"><?php foreach ($questions as $index => $question): ?><div class="card mb-3"><div class="card-body"><h2 class="h5"><?= $index + 1 ?>. <?= e($question['question_text']) ?></h2><?php foreach ($question['options'] as $optionIndex => $option): ?><div class="form-check mt-2"><input class="form-check-input" type="radio" name="answers[<?= (int)$question['id'] ?>]" id="option-<?= (int)$option['id'] ?>" value="<?= (int)$option['id'] ?>"><label class="form-check-label" for="option-<?= (int)$option['id'] ?>"><strong><?= chr(65 + $optionIndex) ?>.</strong> <?= e($option['option_text']) ?></label></div><?php endforeach; ?></div></div><?php endforeach; ?><button class="btn btn-primary" type="submit" <?= !$questions ? 'disabled' : '' ?>>Submit quiz</button></form><?php endif; ?></div>
<?php require __DIR__ . '/../includes/footer.php'; ?>
